import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"什么是交易的确定性？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易确定性/没有确定性。或者换个说法更合理——优势.md","filePath":"stock/交易确定性/没有确定性。或者换个说法更合理——优势.md"}'),o={name:"stock/交易确定性/没有确定性。或者换个说法更合理——优势.md"};function r(s,t,n,c,i,d){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="什么是交易的确定性" tabindex="-1">什么是交易的确定性？ <a class="header-anchor" href="#什么是交易的确定性" aria-label="Permalink to &quot;什么是交易的确定性？&quot;">​</a></h1><p>我觉得更好的说法是，没有确定性。或者换个说法更合理——优势。</p><p>我在这里开单，因为这个地方有确定性，不准确。</p><p>我在这里开单，因为这个地方有优势，准确。</p><p>优势的本质是我在成功率上占超过50%，而不是100%的确定。</p><p>任何一笔交易都不能完全确定。</p><p>不要被确定性蒙蔽。确定性的意思是，我是正确的，优势的意思是对我有利，但不一定是我赢。</p><p>从交易心理上讲：</p><p>有确定性，我不用止损，我是确定的。亏损的时候我可以加保证金。只要我有钱，只要这笔交易还没有爆仓，我就是正确的。</p><p>有优势，只是优势不能保证100%成功，优势一旦转为劣势，我就不能继续添加筹码了，反而止损认输是正确选择。</p>',10)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
